<div class="expertise-grid"><?php $items=get_posts(['post_type'=>'expertise','numberposts'=>-1,'orderby'=>'menu_order','order'=>'ASC']); foreach($items as $item): ?><a class="expertise-card" href="<?php echo esc_url(get_permalink($item)); ?>"><?php echo rzz_icon($item->post_name); ?><div><h3><?php echo esc_html($item->post_title); ?></h3><p><?php echo esc_html(rzz_card_summary($item)); ?></p></div><?php echo rzz_arrow(); ?></a><?php endforeach; ?></div>